import {day,addDays} from './domain.js';
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',study:'m9 5 10 7-10 7Z',library:'M4 3h5v18H4zM10 3h4v18h-4zM16 4l4-1 3 17-4 1Z',dashboard:'M4 20V10h4v10zM10 20V4h4v16zM16 20v-7h4v7Z',import:'M12 3v12m-5-5 5 5 5-5M4 15v5h16v-5',data:'M4 7c0-5 16-5 16 0s-16 5-16 0m0 0v10c0 5 16 5 16 0V7M4 12c0 5 16 5 16 0',arrow:'M4 12h16m-6-6 6 6-6 6',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',audio:'M4 9v6h4l5 4V5L8 9ZM16 8q6 4 0 8',leaf:'M5 19C3 6 12 2 21 3c0 10-5 16-16 16Zm0 0L16 8',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',target:'M20 12a8 8 0 1 1-8-8m0 8 8-8M15 4h5v5',weak:'M12 3 2 21h20ZM12 9v5m0 3v1',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',close:'m6 6 12 12M6 18 18 6',back:'M20 12H4m6-6-6 6 6 6'};
export const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`;
export const badge=s=>`<span class="badge ${esc(s)}">${esc(s)}</span>`;
export const pct=n=>n===null||n===undefined?'—':Math.round(n)+'%';
export const date=v=>v?new Date(v.length===10?v+'T12:00:00+09:00':v).toLocaleDateString('ja-JP',{timeZone:'Asia/Tokyo',month:'short',day:'numeric'}):'—';
export const heading=(k,title,subtitle,extra='')=>`<div class="heading"><div><div class="eyebrow">${esc(k)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${extra}</div>`;
export const panel=(title,body,extra='',cls='')=>`<section class="panel ${cls}"><div class="panel-head"><h2>${esc(title)}</h2>${extra}</div>${body}</section>`;
export const btn=(label,action,primary=false,attrs='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}" ${attrs}>${label}</button>`;
export const linkbtn=(label,href,primary=false)=>`<a class="btn ${primary?'primary':''}" href="${href}">${label}</a>`;
export const field=(label,name,value='',type='text',hint='')=>`<div class="field"><label for="f-${esc(name)}">${esc(label)}</label>${type==='textarea'?`<textarea id="f-${esc(name)}" name="${esc(name)}">${esc(value)}</textarea>`:`<input id="f-${esc(name)}" name="${esc(name)}" type="${type}" value="${esc(value)}">`}${hint?`<small>${esc(hint)}</small>`:''}</div>`;
export const select=(name,choices,value='',empty='すべて',attrs='')=>`<select class="control" name="${esc(name)}" aria-label="${esc(name)}" ${attrs}>${empty!==null?`<option value="">${esc(empty)}</option>`:''}${choices.map(c=>{const v=typeof c==='object'?c.value:c,l=typeof c==='object'?c.label:c;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select>`;
export const notice=(text,kind='')=>`<div class="notice ${kind}">${text}</div>`;
export const stat=(label,value,note,ico='target')=>`<div class="stat"><div class="stat-top"><span>${esc(label)}</span>${icon(ico,16)}</div><div class="stat-value">${esc(value)}</div><div class="stat-note">${esc(note)}</div></div>`;
export const empty=(title,text,action='')=>`<div class="empty"><strong>${esc(title)}</strong>${esc(text)}${action?`<div class="actions" style="justify-content:center;margin-top:18px">${action}</div>`:''}</div>`;
export function itemRows(items){return items.map(i=>`<a href="#item/${esc(i.id)}" class="item-row"><div><div class="item-word">${esc(i.displayText)}</div><small>${esc(i.categories?.join(' · ')||i.type)}</small></div><div class="actions">${i.weak?'<span class="badge weak">Weak</span>':''}${badge(i.status)}${icon('arrow',14)}</div></a>`).join('');}
export function bars(stats,n=7){const days=Array.from({length:n},(_,j)=>addDays(day(),j-n+1)),max=Math.max(1,...days.map(d=>(stats.days[d]?.correct||0)+(stats.days[d]?.incorrect||0)));return `<div class="mini-bars">${days.map(d=>{const v=(stats.days[d]?.correct||0)+(stats.days[d]?.incorrect||0);return `<div class="bar-cell" title="${d}: ${v}回答"><div class="bar" style="height:${Math.max(3,72*v/max)}px"></div><small>${d.slice(5).replace('-','/')}</small></div>`;}).join('')}</div>`;}
export const modeName=m=>({mixed:'おまかせ',recognition:'Recognition','cloze-select':'Cloze Select','cloze-input':'Cloze Input',recall:'Recall',production:'Production'}[m]||m);
export function shell(route,content){const nav=[['home','Home'],['study','Study'],['library','Library'],['dashboard','Review Dashboard'],['import','Add / Import'],['data','Data Management']];return `<div class="shell"><aside class="sidebar"><a class="brand" href="#home"><span class="brandmark">${icon('leaf',24)}</span><span>Personal Vocabulary<small>YOUR WORDS, IN PRACTICE</small></span></a><div><p class="nav-label">Workspace</p><nav class="nav" aria-label="メインナビゲーション">${nav.map(([r,l])=>`<a href="#${r}" class="${r===route||(route==='item'&&r==='library')||(route==='edit'&&r==='import')?'active':''}">${icon(r)}<span>${l}</span></a>`).join('')}</nav></div><div class="sidebar-foot"><span class="dot"></span>アプリ共通ストレージ<br>Personal Vocabulary Trainer<br><span style="font-size:10px">MVP 1.2 · Personal workspace</span></div></aside><div class="body"><header class="topbar"><strong>Vocabulary / <span class="text-muted">${esc(nav.find(n=>n[0]===route)?.[1]||'Item Detail')}</span></strong><div class="topright"><span>${new Date().toLocaleDateString('en-US',{timeZone:'Asia/Tokyo',month:'short',day:'numeric',year:'numeric'})}</span><span class="avatar">P</span></div></header><main id="main" tabindex="-1">${content}</main></div></div>`;}
